// Playbook JSON loader: the books live in the Worker's static assets (worker/public/data/playbooks, generated by
// tools/playbooks-extract.mts) and are cached per isolate so a play call costs one JSON parse at most once. loadTeamBook
// is the book a team actually runs: its stock book unless its coach saved edits on the Playbook page (web_playbook_edits,
// migration 0027), which are composed over the stock books they draw from (@ncaa/ncaa14 composeBook).
import type { Book, BookIndex } from './types.js';
import { booksNeeded, composeBook, compileCustom, type BookEdits } from '@ncaa/ncaa14';
import { getPlaybookEdit } from '../../db/queries.js';

const cache = new Map<string, Promise<unknown>>();
async function asset<T>(assets: Fetcher, origin: string, path: string): Promise<T> {
  const key = path; let p = cache.get(key) as Promise<T> | undefined;
  if (!p) { p = assets.fetch(new Request(origin + path)).then(async (r) => { if (!r.ok) throw new Error(`asset ${path} -> ${r.status}`); return (await r.json()) as T; }); cache.set(key, p); p.catch(() => cache.delete(key)); }
  return p;
}
export const loadIndex = (assets: Fetcher, origin: string) => asset<BookIndex>(assets, origin, '/data/playbooks/index.json');
export const loadBook = (assets: Fetcher, origin: string, id: number) => asset<Book>(assets, origin, `/data/playbooks/${id}.json`);

// TEAM.TOPB / TDPB are indexes (PLAB.BGID) into the playbook list, one list per side; the FCS mod keeps EA's ids.
export function teamBooks(index: BookIndex, raw: Record<string, unknown> | null | undefined): { offBook: number; defBook: number; offName: string; defName: string } {
  const topb = Number(raw?.['TOPB']), tdpb = Number(raw?.['TDPB']);
  const off = index.books.find((b) => b.side === 'off' && b.bgid === topb) ?? index.books.find((b) => b.side === 'off' && b.name === 'Multiple') ?? index.books.find((b) => b.side === 'off')!;
  const def = index.books.find((b) => b.side === 'def' && b.bgid === tdpb) ?? index.books.find((b) => b.side === 'def' && b.name === '4-3') ?? index.books.find((b) => b.side === 'def')!;
  return { offBook: off.id, defBook: def.id, offName: off.name, defName: def.name };
}
const parseRaw = (raw: string | null | undefined): Record<string, unknown> | null => { try { return JSON.parse(raw || 'null'); } catch { return null; } };
// the team's stock book of one side, from TEAM.TOPB / TDPB in its raw_json
export async function loadStockBook(assets: Fetcher, origin: string, team: { raw_json: string | null }, side: 'off' | 'def'): Promise<Book> {
  const b = teamBooks(await loadIndex(assets, origin), parseRaw(team.raw_json));
  return loadBook(assets, origin, side === 'off' ? b.offBook : b.defBook);
}
// the stock books edits draw from (base + every `from`), loaded; a missing one throws like any asset miss
export const loadEditBooks = async (assets: Fetcher, origin: string, edits: BookEdits): Promise<Map<number, Book>> => new Map(await Promise.all(booksNeeded(edits).map(async (id) => [id, await loadBook(assets, origin, id)] as const)));
// the book edits compose to, drawn plays compiled in (@ncaa/ncaa14 compileCustom); throws when the edits do not compose
export const composeEdits = async (assets: Fetcher, origin: string, edits: BookEdits): Promise<Book> => composeBook(edits, await loadEditBooks(assets, origin, edits), { custom: compileCustom });

// custom: the book is composed from the team's saved edits; edits: the saved edits when they parse (also when they no
// longer compose, so a page can say so; custom is false then and the book is the stock one)
export interface TeamBook { book: Book; custom: boolean; edits: BookEdits | null }
// one composition per team and side, good while the stored edits text is the one it was made from (updated_at alone has
// second resolution, so two quick saves could share it)
const composed = new Map<string, { json: string; p: Promise<TeamBook> }>(); const warned = new Set<string>();
export async function loadTeamBook(env: { ASSETS: Fetcher; DB: D1Database }, origin: string, dynastyId: number, team: { tgid: number; raw_json: string | null }, side: 'off' | 'def'): Promise<TeamBook> {
  const stock = async (edits: BookEdits | null): Promise<TeamBook> => ({ book: await loadStockBook(env.ASSETS, origin, team, side), custom: false, edits });
  const row = await getPlaybookEdit(env.DB, dynastyId, team.tgid, side);
  if (!row) return stock(null);
  const key = `${dynastyId}:${team.tgid}:${side}`; const hit = composed.get(key);
  if (hit && hit.json === row.edits_json) return hit.p;
  const p = (async () => {
    let edits: BookEdits | null = null;
    try { edits = JSON.parse(row.edits_json) as BookEdits; return { book: await composeEdits(env.ASSETS, origin, edits), custom: true, edits }; }
    catch (e) { // stale edits (a stock book changed under them) or malformed JSON: the stock book, said once per save
      const w = `${key}:${row.updated_at}`; if (!warned.has(w)) { if (warned.size > 256) warned.clear(); warned.add(w); console.error(`playbook edits of team ${team.tgid} (${side}) in dynasty ${dynastyId} do not compose; using the stock book: ${(e as Error).message}`); }
      return stock(edits);
    }
  })();
  composed.set(key, { json: row.edits_json, p }); p.catch(() => composed.delete(key));
  return p;
}
